const state={items:[],poses:[],cached:new Set(),favorites:new Set(),added:[],results:[],tasks:[],page:'home',tab:'推荐',category:'全部',query:'',limit:24,selected:null,pose:null,angle:'正面',style:'自然手机感',person:null,personUrl:null,config:{protocol:'codex-local',endpoint:'',model:'',key:'',connected:false}};
let objects=[];
const objectURL=file=>{const url=URL.createObjectURL(file);objects.push(url);return url;};
$('app').innerHTML=`<header><a id="brand">衣见<span>穿出新的自己</span></a><div><button id="info" aria-label="说明">ⓘ</button><button id="settings" aria-label="接口设置">⚙</button></div></header><main id="main"></main><nav><button id="homeNav" class="active">⌂<span>发现穿搭</span></button><button id="addNav">＋<span>添加穿搭</span></button><button id="resultsNav">▧<span>我的成片</span></button></nav><dialog id="detail"></dialog><dialog id="picker"></dialog><dialog id="config"></dialog><dialog id="saveHelp"></dialog><dialog id="help"><h2>本次使用说明</h2><p class="muted">本机 ChatGPT：直接图片编辑接口 · 2026-10-30</p><p>穿搭必选，人物可选；默认自然站立。人物参考帮助保持身份，不选则生成虚构成年人。</p><p>API Key、收藏、上传和任务仅在本次页面中使用。电脑本地运行时，生成成片自动保存到“下载／衣见成片”。手机网页需点击“存到相册”，在系统分享面板完成；无法静默写入相册。刷新清空页面记录，不会删除已保存的图片。生成时图片会发送给你选择的服务并由其计费；刷新不会取消已经提交的上游任务。</p><p>内置为 AI 生成的虚构穿搭与自绘姿势示意，镜头角度按所选文字要求传递。请只导入你有权使用的图片。</p><button class="primary" id="helpClose">知道了</button></dialog><input type="file" id="upload" accept="image/png,image/jpeg,image/webp" hidden><input type="file" id="personUpload" accept="image/png,image/jpeg,image/webp" hidden><button id="taskDock" class="taskdock" hidden></button><div id="toast" role="status"></div>`;
function mobileDevice(){return navigator.userAgentData?.mobile===true||/Android|iPhone|iPad|iPod/i.test(navigator.userAgent)||(/Macintosh/.test(navigator.userAgent)&&navigator.maxTouchPoints>1);}
function saveTarget(){return mobileDevice()?'mobile':(['localhost','127.0.0.1'].includes(location.hostname)?'desktop-local':'desktop-browser');}
function fileName(r){return r.savedName||('outfit-'+r.id+'.'+r.ext);}
function saveAction(r){return r.mobile?`<button data-save="${r.id}" class="text">存到相册 ↓</button><a class="text" href="${r.url}" download="${esc(fileName(r))}" aria-label="下载图片到文件">下载</a>`:`<a href="${r.url}" download="${esc(fileName(r))}" class="text">${r.savedTo?'另存一份 ↓':'下载图片 ↓'}</a>`;}
function saveCaption(r){return r.savedTo?'已保存到电脑':r.saveError?'自动保存失败':r.mobile?'待存到相册':'请下载保存';}
function saveInfo(r){const el=$('saveHelp');el.innerHTML=`<h2>${r.mobile?'存到手机相册':'成片保存'}</h2><p>${r.savedTo?'已保存到：'+esc(r.savedTo):r.saveError?esc(r.saveError):r.mobile?'点击“存到相册”，在系统分享面板中选择“存储图像”或对应相册操作。不同手机的选项可能不同；若不支持，可以下载图片后从文件中保存，或在成片页长按图片保存。':'请点击下载图片保存到这台设备。'}</p><button id="saveHelpClose" class="primary">知道了</button>`;$('saveHelpClose').onclick=()=>el.close();openDialog('saveHelp');}
async function saveToAlbum(r){
 if(!r)return;const file=new File([r.blob],fileName(r),{type:r.blob.type});
 let supported=false;try{supported=!!navigator.share&&!!navigator.canShare?.({files:[file]});}catch{}
 if(supported){
  try{await navigator.share({files:[file],title:'衣见穿搭照'});}catch(error){if(error.name!=='AbortError'){toast('系统分享暂不可用，可下载或长按图片保存');saveInfo(r);}}
 }else saveInfo(r);
 // Sharing success cannot prove that the user chose Photos, so never claim album save success.
}
function bindSaveActions(root=document){root.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>saveToAlbum(state.results.find(r=>r.id===b.dataset.save)));root.querySelectorAll('[data-save-info]').forEach(b=>b.onclick=()=>saveInfo(state.results.find(r=>r.id===b.dataset.saveInfo)));}
const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
function enter(el){if(!el||reducedMotion.matches||!window.anime)return;anime.animate(el,{opacity:[0,1],translateY:[10,0],duration:360,ease:'out(3)'});}
function openDialog(id){const el=$(id);el.showModal();if(!reducedMotion.matches&&window.anime)anime.animate(el,{opacity:[0,1],translateY:[24,0],scale:[0.98,1],duration:320,ease:'out(3)'});}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),3000);}
const categories={'全部':'全部','春':'春日','夏':'夏日','秋':'秋日','冬':'冬日','ランジェリー':'内搭','パーティ':'派对','水着':'泳装','セクシー':'其他'};
function all(){return [...state.added,...state.items];}
function costumeThumb(o){return o.local?o.url:o.localAsset;}
function poseThumb(p){return p.localAsset;}
async function assetDataUrl(url){const response=await fetch(url,{cache:'no-store'});if(!response.ok)throw Error('参考图读取失败');const blob=await response.blob();if(!blob.type.includes('svg'))return read(blob);const image=new Image();const source=URL.createObjectURL(blob);try{image.src=source;await image.decode();const canvas=document.createElement('canvas');canvas.width=image.naturalWidth*2;canvas.height=image.naturalHeight*2;canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/png');}finally{URL.revokeObjectURL(source);}}
function title(o){return o.name||((categories[o['カテゴリ']]||o['カテゴリ'])+'穿搭 · '+o.id);}
function nav(page){state.page=page;document.querySelectorAll('nav button').forEach(x=>x.classList.remove('active'));$(page.startsWith('result')?'resultsNav':'homeNav').classList.add('active');}
function home(){nav('home');$('main').innerHTML=`<div class="tabs"><button id="recommend" class="${state.tab==='推荐'?'active':''}">推荐</button><button id="favorites" class="${state.tab==='已收藏'?'active':''}">已收藏</button><button id="addTop" aria-label="添加穿搭">＋</button></div><input id="search" class="search" placeholder="搜索穿搭" value="${esc(state.query)}"><div class="chips">${['全部','春','夏','秋','冬'].map(c=>`<button data-category="${c}" class="${state.category===c?'active':''}">${categories[c]}</button>`).join('')}</div><div id="cards" class="cards"></div><button class="more" id="more">查看更多</button>`;
 $('recommend').onclick=()=>{state.tab='推荐';state.limit=24;home();};$('favorites').onclick=()=>{state.tab='已收藏';state.limit=24;home();};$('addTop').onclick=()=>$('upload').click();
 $('search').oninput=e=>{state.query=e.target.value;state.limit=24;cards();};document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{state.category=b.dataset.category;state.limit=24;home();});$('more').onclick=()=>{state.limit+=24;cards();};cards();enter($('main'));}
function cards(){const list=all().filter(o=>(state.tab!=='已收藏'||state.favorites.has(o.id))&&(state.category==='全部'||o['カテゴリ']===state.category)&&(title(o)+' '+(o['キーワード']||'')).toLowerCase().includes(state.query.toLowerCase()));$('cards').innerHTML=list.slice(0,state.limit).map(o=>`<article><button class="card" data-outfit="${esc(o.id)}"><img loading="lazy" src="${esc(costumeThumb(o))}" alt="${esc(title(o))}"><span>${esc(title(o))}</span></button><button class="heart ${state.favorites.has(o.id)?'on':''}" data-favorite="${esc(o.id)}" aria-label="收藏">${state.favorites.has(o.id)?'♥':'♡'}</button></article>`).join('')||'<p class="empty">这里还没有穿搭</p>';$('more').hidden=list.length<=state.limit;document.querySelectorAll('[data-outfit]').forEach(b=>b.onclick=()=>detail(all().find(o=>o.id===b.dataset.outfit)));document.querySelectorAll('[data-favorite]').forEach(b=>b.onclick=()=>{favorite(b.dataset.favorite);cards();});}
function favorite(id){state.favorites.has(id)?state.favorites.delete(id):state.favorites.add(id);}
function detail(o){state.selected=o;renderDetail();if(!$('detail').open)openDialog('detail');}
function renderDetail(){const o=state.selected;if(!o)return;$('detail').innerHTML=`<div class="modalhead"><button id="detailClose" aria-label="返回">←</button><span>试穿这套</span><button id="detailFavorite" aria-label="收藏">${state.favorites.has(o.id)?'♥':'♡'}</button></div><img class="outfitHero" src="${esc(costumeThumb(o))}" alt="${esc(title(o))}"><div class="detailbody"><h2>${esc(title(o))}</h2><button class="row" id="personChoice"><span>人物参考</span><span>${state.person?'<img class="avatar" src="'+state.personUrl+'"> 已选择':'不使用'} ›</span></button>${state.person?'<button class="text" id="personRemove">本次不使用人物参考</button>':''}<button class="row" id="poseChoice"><span>姿势</span><span>${esc(state.pose?state.pose['姿势名称']:'自然站立')} ›</span></button><label class="row">摄影风格<select id="photoStyle">${['自然手机感','街头随拍','直闪摄影','干净影棚','时尚杂志'].map(v=>`<option ${v===state.style?'selected':''}>${v}</option>`).join('')}</select></label><details><summary>补充要求</summary><textarea id="extra" rows="2" maxlength="1500" placeholder="还有什么想法？"></textarea></details><div class="micro"><span>9:16 · 手机竖图</span><button id="modelSettings" class="text">${state.config.protocol==='codex-local'?(state.config.connected?'ChatGPT 已连接':'连接 ChatGPT'):(state.config.key?'已配置接口':'填写 API Key')} ⚙</button></div><button id="generate" class="primary">生成穿搭照 ↗</button><p id="generationStatus" role="status"></p></div>`;
 $('detailClose').onclick=()=>{$('detail').close();if($('cards'))cards();};$('detailFavorite').onclick=()=>{favorite(o.id);$('detailFavorite').textContent=state.favorites.has(o.id)?'♥':'♡';};$('personChoice').onclick=()=>$('personUpload').click();if($('personRemove'))$('personRemove').onclick=()=>{state.person=null;state.personUrl=null;renderDetail();};$('poseChoice').onclick=posePicker;$('photoStyle').onchange=e=>state.style=e.target.value;$('modelSettings').onclick=settings;$('generate').onclick=generate;}
function posePicker(){let category='全部';let query='';function draw(){$('picker').innerHTML=`<div class="modalhead"><button id="poseClose">←</button><h2>选择姿势</h2><button id="natural" class="text">自然站立</button></div><input id="poseSearch" placeholder="搜索姿势" value="${esc(query)}"><div class="chips">${['全部',...new Set(state.poses.map(p=>p['分类']))].map(c=>`<button data-posecat="${esc(c)}" class="${c===category?'active':''}">${esc(c)}</button>`).join('')}</div><div id="poseCards" class="posecards"></div>`;$('poseClose').onclick=()=>$('picker').close();$('natural').onclick=()=>{state.pose=null;state.angle='正面';$('picker').close();renderDetail();};$('poseSearch').oninput=e=>{query=e.target.value;drawCards();};document.querySelectorAll('[data-posecat]').forEach(b=>b.onclick=()=>{category=b.dataset.posecat;draw();});drawCards();}
 function drawCards(){$('poseCards').innerHTML=state.poses.filter(p=>(category==='全部'||p['分类']===category)&&p['检索'].includes(query)).map(p=>`<button data-pose="${p.id}" class="posecard"><img loading="lazy" src="${poseThumb(p)}" alt="${esc(p['姿势名称'])}"><span>${esc(p['姿势名称'])}</span></button>`).join('');document.querySelectorAll('[data-pose]').forEach(b=>b.onclick=()=>poseAngles(state.poses.find(p=>p.id===b.dataset.pose)));}draw();openDialog('picker');}
function poseAngles(p){const prefix=p.id.replace(/_front$/,'');const angles=[['front','正面'],['high','俯视'],['low','仰视'],['side','侧面'],['diag','斜侧']];let angle=angles.find(a=>a[1]===state.angle)||angles[0];function draw(){$('picker').innerHTML=`<div class="modalhead"><button id="backPoses">←</button><h2>${esc(p['姿势名称'])}</h2></div><img class="poseHero" src="${esc(p.localAsset)}" alt="${esc(p['姿势名称'])}"><div class="chips">${angles.map(a=>`<button data-angle="${a[0]}" class="${a[0]===angle[0]?'active':''}">${a[1]}</button>`).join('')}</div><button id="confirmPose" class="primary">使用这个姿势</button>`;$('backPoses').onclick=()=>{$('picker').close();posePicker();};document.querySelectorAll('[data-angle]').forEach(b=>b.onclick=()=>{angle=angles.find(a=>a[0]===b.dataset.angle);draw();});$('confirmPose').onclick=()=>{state.pose={...p};state.angle=angle[1];$('picker').close();renderDetail();};}draw();}
const presets={'codex-local':{endpoint:'',placeholder:''},doubao:{endpoint:'https://ark.cn-beijing.volces.com/api/v3/images/generations',placeholder:'豆包 Seedream 模型 ID 或接入点 ID'},'openai-edits':{endpoint:'https://api.openai.com/v1/images/edits',placeholder:'GPT 图像模型 ID'},globalrouter:{endpoint:'https://api.globalrouter.com/api/v1/images',placeholder:'支持图生图的模型 ID'}};
function settings(){const c=state.config;$('config').innerHTML=`<div class="modalhead"><button id="configClose">←</button><h2>生成方式</h2><span></span></div><form id="settingsForm" autocomplete="off"><label>连接方式<select id="protocol"><option value="codex-local">本机 ChatGPT</option><option value="doubao">豆包 · 火山方舟</option><option value="openai-edits">GPT · OpenAI / 兼容接口</option><option value="globalrouter">GlobalRouter</option></select></label><div id="localPanel"><div class="connectioncard"><b>ChatGPT</b><p>使用这台电脑已有的 ChatGPT / Codex 登录</p><span id="connectionState">${c.connected?'本机登录可用':'尚未连接'}</span></div><p class="muted">凭据只在本机读取，不另存。生成使用账号额度，图片仍由 ChatGPT 处理。</p></div><div id="apiFields"><label>接口地址<input id="endpoint" type="url" required spellcheck="false" value="${esc(c.endpoint)}"></label><label>图生图模型<input id="model" required value="${esc(c.model)}" placeholder="${presets[c.protocol].placeholder}" spellcheck="false"></label><label>API Key<input id="key" type="password" required autocomplete="off" spellcheck="false"></label></div><p id="connectionError" class="muted" role="status"></p><button id="connectSubmit" class="primary">连接本机 ChatGPT</button><button type="button" id="forgetKey" class="text">断开 / 清除凭据</button></form>`;
 $('protocol').value=c.protocol;$('key').value=c.key;
 function mode(){const local=$('protocol').value==='codex-local';$('localPanel').hidden=!local;$('apiFields').hidden=local;['endpoint','model','key'].forEach(id=>$(id).disabled=local);$('connectSubmit').textContent=local?'连接本机 ChatGPT':'完成';$('connectionError').textContent='';}
 $('protocol').onchange=()=>{const p=presets[$('protocol').value];$('endpoint').value=p.endpoint;$('model').value='';$('model').placeholder=p.placeholder;$('key').value='';mode();};mode();
 $('configClose').onclick=()=>$('config').close();$('settingsForm').onsubmit=async e=>{e.preventDefault();if($('protocol').value==='codex-local'){
 $('connectSubmit').disabled=true;$('connectionError').textContent='正在检查本机登录…';
 try{const response=await fetch('/api/local-chatgpt/connect',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}',cache:'no-store'});const d=await response.json();if(!response.ok||!d.connected)throw Error(d.error||'连接失败');state.config={protocol:'codex-local',endpoint:'',model:'',key:'',connected:true};$('config').close();if($('detail').open)renderDetail();toast('本机 ChatGPT 已连接');}catch(error){$('connectionError').textContent=error.message;}finally{$('connectSubmit').disabled=false;}
 }else{state.config={protocol:$('protocol').value,endpoint:$('endpoint').value.trim(),model:$('model').value.trim(),key:$('key').value.trim(),connected:false};$('key').value='';$('config').close();if($('detail').open)renderDetail();toast('接口已配置');}};
 $('forgetKey').onclick=()=>{state.config.key='';state.config.connected=false;$('key').value='';$('connectionState').textContent='尚未连接';if($('detail').open)renderDetail();toast('本次连接已断开');};openDialog('config');}
function validFile(file){if(!file)return false;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8000000){toast('请选择 8 MB 以内的 PNG、JPEG 或 WebP');return false;}return true;}
$('upload').onchange=e=>{const file=e.target.files[0];e.target.value='';if(!validFile(file))return;const o={id:'local-'+crypto.randomUUID(),name:file.name.replace(/\.[^.]+$/,''),local:true,url:objectURL(file),file};state.added.unshift(o);home();detail(o);};
$('personUpload').onchange=e=>{const file=e.target.files[0];e.target.value='';if(!validFile(file))return;state.person=file;state.personUrl=objectURL(file);renderDetail();};
function read(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('图片读取失败'));r.readAsDataURL(file);});}
const MAX_ACTIVE=2, MAX_PENDING=8;
const taskLabels={queued:'排队中',reading:'准备图片',running:'生成中',succeeded:'已完成',failed:'生成失败',unknown:'结果待核对',cancelled:'已取消'};
const pending=t=>['queued','reading','running'].includes(t.status);
function activeCount(){return state.tasks.filter(t=>['reading','running'].includes(t.status)).length;}
let lastSubmission=0;
function generate(){
 if(Date.now()-lastSubmission<600)return;
 if(state.config.protocol==='codex-local'?!state.config.connected:(!state.config.key||!state.config.model)){settings();return;}
 if(state.tasks.filter(pending).length>=MAX_PENDING){toast('最多保留 8 个待完成任务');return;}
 const snapshot={o:state.selected,pose:state.pose?{...state.pose}:null,angle:state.angle,style:state.style,person:state.person,personUrl:state.personUrl,config:{...state.config},saveTarget:saveTarget(),extra:$('extra')?.value||''};
 const task={id:crypto.randomUUID(),status:'queued',created:Date.now(),snapshot,name:title(snapshot.o),thumb:costumeThumb(snapshot.o),pose:snapshot.pose?snapshot.pose['姿势名称']:'自然站立'};
 lastSubmission=Date.now();state.tasks.unshift(task);$('detail').close();syncTasks();toast('已加入生成任务，可继续选穿搭');pump();
}
function pump(){for(const task of [...state.tasks].reverse()){if(activeCount()>=MAX_ACTIVE)break;if(task.status==='queued')void runTask(task);}}
async function runTask(task){const s=task.snapshot;task.status='reading';task.started=Date.now();syncTasks();try{
 const references=[s.o.local?await read(s.o.file):await assetDataUrl(s.o.localAsset)];if(s.person)references.push(await read(s.person));if(s.pose)references.push(await assetDataUrl(s.pose.localAsset));
 task.status='running';syncTasks();const body=JSON.stringify({...s.config,references,saveTarget:s.saveTarget,outfitName:task.name,hasPerson:!!s.person,hasPose:!!s.pose,pose:task.pose+'，'+s.angle,style:s.style,extra:s.extra});s.config.key='';
 const response=await fetch('/api/generate',{method:'POST',headers:{'Content-Type':'application/json'},cache:'no-store',body});
 const d=await response.json();if(!response.ok){const error=Error(d.error||'生成失败');error.code=d.errorCode;error.diagnostics=d.diagnostics;throw error;}if(!/^data:image\/(png|jpeg|webp);base64,/.test(d.image||''))throw Error('未返回图片');
 const blob=await(await fetch(d.image)).blob();const result={id:task.id,url:objectURL(blob),ext:blob.type.split('/')[1],name:task.name,pose:task.pose,snapshot:s,blob,mobile:s.saveTarget==='mobile',savedTo:d.savedTo||'',savedName:d.savedName||'',saveError:d.saveError||''};task.result=result;task.status='succeeded';state.results.unshift(result);toast(result.savedTo?'成片已自动保存到电脑':result.mobile?'成片已完成，点击存到相册':result.saveError?'图片已生成，请手动下载保存':task.name+' 已完成');
 }catch(error){task.errorCode=error.code||'';task.diagnostics=error.diagnostics||null;task.error=error.message||'请求中断，请先核对上游执行状态';task.status=/待核对|先核对|超时|未收到完整|请求中断/.test(task.error)?'unknown':'failed';toast(task.status==='unknown'?'有任务结果待核对':'有任务未生成成功');}
 finally{s.config.key='';task.finished=Date.now();syncTasks();pump();}}
function syncTasks(){
 const remaining=state.tasks.filter(pending).length;const dock=$('taskDock');dock.hidden=!remaining;dock.innerHTML=`<span class="orb"></span><span>${activeCount()} 个生成中${remaining>activeCount()?' · '+(remaining-activeCount())+' 个排队':''}</span><span>查看 ↗</span>`;
 $('resultsNav').innerHTML=`▧<span>我的成片${remaining?' <b class="navbadge">'+remaining+'</b>':''}</span>`;
 if(state.page==='results'&&$('taskList'))renderTasks();
}
function results(){nav('results');window.scrollTo({top:0,behavior:'instant'});$('main').innerHTML=`<div class="heading"><h1>我的成片</h1><button class="text" id="clearResults">清空列表</button></div><div class="tasksummary" id="taskSummary"></div><div id="taskList" class="tasklist"></div><p class="muted">${mobileDevice()?'成片完成后，请存到相册':'电脑本地生成的成片自动保存在下载／衣见成片'}</p>`;renderTasks();enter($('main'));
 $('clearResults').onclick=()=>{state.tasks.filter(t=>t.status==='succeeded').forEach(t=>URL.revokeObjectURL(t.result.url));state.tasks=state.tasks.filter(pending);state.results=[];renderTasks();syncTasks();};}
function elapsed(t){return Math.max(0,Math.floor(((t.finished||Date.now())-(t.started||t.created))/1000))+'s';}
function taskDiagnostic(t){if(!t.diagnostics)return '';const d=t.diagnostics;const detail=d.route?`接口：${esc(d.route)}<br>HTTP ${esc(d.httpStatus??'')}<br>${esc(d.upstreamCode||'')}<br>${esc(d.upstreamMessage||'')}`:`生图工具：${d.outputTypes?.image_generation_call||d.finalImages||d.partialImages?'已检测到':'未检测到'}<br>最终输出：${d.finalImages||0} · 预览：${d.partialImages||0}<br>响应结束标记：${d.completed?'已收到':'未收到'}`;return `<details class="taskdiagnostic"><summary>诊断 ⓘ</summary><p>${esc(t.errorCode)}<br>${detail}</p></details>`;}
function taskHTML(t){const success=t.status==='succeeded',waiting=pending(t);return `<article class="taskcard ${t.status}" data-task="${t.id}"><div class="taskvisual">${success?`<button data-result="${t.id}" class="taskimage"><img src="${t.result.url}" alt="${esc(t.name)}的生成结果"></button>`:`<img src="${esc(t.thumb)}" alt="${esc(t.name)}">${waiting?'<div class="taskveil"><span class="loader"></span></div>':''}`}</div><div class="taskmeta"><span class="statuspill ${t.status}">${waiting?'<i></i>':''}${t.errorCode==='CONTENT_REJECTED'?'未通过检查':taskLabels[t.status]}</span><span class="tasktime" data-time="${t.id}">${elapsed(t)}</span><h2>${esc(t.name)}</h2><p>${esc(t.pose)} · ${esc(t.snapshot.style)}</p>${success?`<button class="save-state ${t.result.saveError?'warning':''}" data-save-info="${t.id}">${saveCaption(t.result)} ⓘ</button>`:''}${t.error?`<p class="taskerror">${esc(t.error)}</p>${taskDiagnostic(t)}`:''}<div class="taskactions">${success?`<button data-result="${t.id}" class="text">查看成片 ↗</button>${saveAction(t.result)}`:t.status==='queued'?`<button data-cancel="${t.id}" class="text">取消排队</button>`:!waiting?`<button data-prepare="${t.id}" class="text">${t.errorCode==='CONTENT_REJECTED'?'修改参考素材':'重新准备'}</button>`:'<span class="muted">可以继续选其他穿搭</span>'}</div></div></article>`;}
function renderTasks(){const list=$('taskList');if(!list)return;const counts=state.tasks.reduce((a,t)=>(a[t.status]=(a[t.status]||0)+1,a),{});$('taskSummary').textContent=state.tasks.length?`${state.tasks.filter(pending).length} 个待完成 · ${counts.succeeded||0} 张成片`:'';
 if(!state.tasks.length){list.innerHTML='<div class="empty empty-state"><span>✧</span><h2>下一张，是什么样的你</h2><p>选一套穿搭，开始试试</p><button class="text" id="exploreOutfits">发现穿搭 ↗</button></div>';$('exploreOutfits').onclick=home;return;}
 list.querySelector('.empty')?.remove();list.querySelectorAll('[data-task]').forEach(el=>{if(!state.tasks.some(t=>t.id===el.dataset.task))el.remove();});
 for(const t of [...state.tasks].reverse()){let el=list.querySelector(`[data-task="${t.id}"]`);if(!el){list.insertAdjacentHTML('afterbegin',taskHTML(t));el=list.firstElementChild;el.dataset.status=t.status;enter(el);}else if(el.dataset.status!==t.status){const box=document.createElement('div');box.innerHTML=taskHTML(t);const next=box.firstElementChild;next.dataset.status=t.status;el.replaceWith(next);if(t.status==='succeeded')enter(next);}}
 bindSaveActions(list);list.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>showResult(state.results.find(r=>r.id===b.dataset.result)));list.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=()=>{const t=state.tasks.find(t=>t.id===b.dataset.cancel);if(t?.status==='queued'){t.status='cancelled';t.finished=Date.now();t.snapshot.config.key='';syncTasks();pump();}});list.querySelectorAll('[data-prepare]').forEach(b=>b.onclick=()=>prepare(state.tasks.find(t=>t.id===b.dataset.prepare).snapshot));}
function prepare(s){state.person=s.person;state.personUrl=s.personUrl;state.pose=s.pose;state.angle=s.angle;state.style=s.style;detail(s.o);if($('extra'))$('extra').value=s.extra;}
function showResult(r){if(!r)return;nav('result');$('main').innerHTML=`<div class="heading"><button id="backResults" class="text">← 我的成片</button><div class="save-buttons">${saveAction(r)}</div></div><button class="save-state ${r.saveError?'warning':''}" data-save-info="${r.id}">${saveCaption(r)} ⓘ</button><img class="resultHero" src="${r.url}" alt="实际生成照片"><div class="heading"><h2>${esc(r.name)}</h2><span>${esc(r.pose)}</span></div><button class="primary" id="again">换个姿势再试</button>`;bindSaveActions($('main'));$('backResults').onclick=results;$('again').onclick=()=>{prepare(r.snapshot);posePicker();};enter($('main'));window.scrollTo({top:0,behavior:'smooth'});}
setInterval(()=>{document.querySelectorAll('[data-time]').forEach(el=>{const t=state.tasks.find(t=>t.id===el.dataset.time);if(t&&pending(t))el.textContent=elapsed(t);});},1000);
$('taskDock').onclick=results;
$('brand').onclick=home;$('homeNav').onclick=home;$('addNav').onclick=()=>$('upload').click();$('resultsNav').onclick=results;$('settings').onclick=settings;$('info').onclick=()=>openDialog('help');$('helpClose').onclick=()=>$('help').close();
window.addEventListener('pagehide',()=>{state.config.key='';state.tasks.forEach(t=>t.snapshot.config.key='');$('key')&&($('key').value='');objects.forEach(URL.revokeObjectURL);objects=[];state.tasks=[];state.person=null;state.added=[];state.results=[];state.favorites.clear();});
async function init(){try{const [items,poses]=await Promise.all(['catalog.json','poses.json'].map(f=>fetch('/prototype/data/'+f,{cache:'no-store'}).then(r=>{if(!r.ok)throw Error();return r.json();})));state.items=items;state.poses=poses;home();}catch{home();toast('示例暂未加载，可添加本地穿搭');}}init();
